#!/usr/bin/env node
/**
 * LIVE MAINNET BROADCAST TEST
 * 
 * This script orchestrates the user-signed broadcast flow on Pharos Pacific Mainnet.
 * SafeHands holds no keys and does not sign. You must externally sign the transaction 
 * generated by the prepare step and provide the raw signature.
 * 
 * Usage:
 * SAFEHANDS_USER_SIGNED_BROADCAST_ENABLED=true SAFEHANDS_LIVE_BROADCAST_TEST=true node scripts/live-broadcast-test.mjs
 */

import readline from "node:readline/promises";
import { handleWalletPrepare } from "../dist/api/walletPrepareRoutes.js";
import { handleBroadcastSigned } from "../dist/api/broadcastRoutes.js";

async function run() {
  if (process.env.SAFEHANDS_USER_SIGNED_BROADCAST_ENABLED !== "true" || process.env.SAFEHANDS_LIVE_BROADCAST_TEST !== "true") {
    console.error("❌ This is a live mainnet test that broadcasts real transactions.");
    console.error("   To proceed, you must explicitly opt-in by setting:");
    console.error("   SAFEHANDS_USER_SIGNED_BROADCAST_ENABLED=true");
    console.error("   SAFEHANDS_LIVE_BROADCAST_TEST=true");
    process.exit(1);
  }

  const rl = readline.createInterface({ input: process.stdin, output: process.stdout });
  
  console.log("=== SafeHands Live Broadcast Verification (Mainnet) ===\n");
  const userAddress = await rl.question("Enter your wallet address (0x...): ");
  const recipient = await rl.question("Enter recipient address (0x...): ");
  
  if (!userAddress.startsWith("0x") || !recipient.startsWith("0x")) {
    console.error("Addresses must start with 0x");
    process.exit(1);
  }

  console.log("\n[1] Preparing transaction via /wallet/prepare...");
  const prepareRes = await handleWalletPrepare({
    to: recipient,
    value: "100000000000000", // 0.0001 PROS
    userAddress,
    chainId: 1672
  });

  if (prepareRes.decision === "BLOCK") {
    console.error("❌ Action blocked by policy.", prepareRes);
    process.exit(1);
  }

  console.log("\n✅ Transaction prepared.");
  console.log("Prepared ID:", prepareRes.preparedTransactionId);
  console.log("Wallet Request parameters to sign:");
  console.log(JSON.stringify(prepareRes.walletRequest, null, 2));
  
  console.log("\n[2] *** EXTERNAL ACTION REQUIRED ***");
  console.log("SafeHands does not sign transactions. Please sign the above transaction");
  console.log("using your own wallet (e.g., via a local ethers/viem script or metamask) for chainId 1672.");
  
  const rawSigned = await rl.question("\nPaste the raw signed transaction hex here (0x...): ");
  
  if (!rawSigned.startsWith("0x")) {
    console.error("Raw signed transaction must start with 0x");
    process.exit(1);
  }

  console.log("\n[3] Submitting to /broadcast/signed...");
  try {
    const broadcastRes = await handleBroadcastSigned({
      preparedTransactionId: prepareRes.preparedTransactionId,
      preparedTransactionHash: prepareRes.preparedTransactionHash,
      rawSignedTransaction: rawSigned.trim()
    });
    console.log("\n✅ Success!");
    console.log("Response:", JSON.stringify(broadcastRes, null, 2));
    if (broadcastRes.txHash) {
      console.log(`\nView on Explorer: https://www.pharosscan.xyz/tx/${broadcastRes.txHash}`);
    }
  } catch (err) {
    console.error("\n❌ Broadcast Failed:");
    console.error(err.message);
  } finally {
    rl.close();
  }
}

run().catch((err) => {
  console.error(err);
  process.exit(1);
});
